class Solution {
public:
 int maxLen(int n,vector<vector<int>>& edges,string label){
  vector<int>adj(n);for(auto&e:edges){adj[e[0]]|=1<<e[1];adj[e[1]]|=1<<e[0];}
  vector<vector<unsigned char>>dp(1<<n,vector<unsigned char>(n*n));queue<array<int,3>>q;int ans=0;
  auto push=[&](int m,int a,int b){if(!dp[m][a*n+b]){dp[m][a*n+b]=1;q.push({m,a,b});}};
  for(int i=0;i<n;++i)push(1<<i,i,i);
  for(auto&e:edges)if(label[e[0]]==label[e[1]])push((1<<e[0])|(1<<e[1]),e[0],e[1]);
  while(!q.empty()){auto t=q.front();q.pop();int m=t[0],a=t[1],b=t[2];ans=max(ans,__builtin_popcount((unsigned)m));
   for(int x=0;x<n;++x)if(!(m>>x&1)&&(adj[a]>>x&1))for(int y=0;y<n;++y)if(x!=y&&!(m>>y&1)&&(adj[b]>>y&1)&&label[x]==label[y])push(m|(1<<x)|(1<<y),x,y);
  }return ans;
 }
};
